; ============================================================
; function secs (normal mode)
; ============================================================

p_secs:

			; main.bas 92: Secs = Str$(t \ System.TicksPerSecond) + "." + Mid$(Str$(100 + (t Mod System.TicksPerSecond) * 100 \ System.TicksPerSecond), 3) + "s"
			dw kw_divvl, var_secs_t, 16, tmp0
			dw kw_strstr, stmp0, tmp0
			dw kw_strcat, stmp0, str23
			dw kw_modvl, var_secs_t, 16, tmp2
			dw kw_mulvl, tmp2, 100, tmp2
			dw kw_divvl, tmp2, 16, tmp2
			dw kw_addl, tmp2, 100, tmp1
			dw kw_strstr, stmp1, tmp1
			dw kw_strmid, stmp1, stmp1, lit_3, lit_255
			dw kw_strcat, stmp0, stmp1
			dw kw_strcpy, var_secs_secs, stmp0
			dw kw_strcat, var_secs_secs, str24
			dw p_secs_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for4_e_go:			ld sp, for4_e
			jp ntc_xn
do6_e_go:			ld sp, do6_e
			jp ntc_xn
ch9_e_go:			ld sp, ch9_e
			jp ntc_xn
if10_e_go:			ld sp, if10_e
			jp ntc_xn
ch11_e_go:			ld sp, ch11_e
			jp ntc_xn
do6_t_go:			ld sp, do6_t
			jp ntc_xn
do13_t_go:			ld sp, do13_t
			ret
do14_t_go:			ld sp, do14_t
			ret
do16_t_go:			ld sp, do16_t
			jp ntc_xn
do17_t_go:			ld sp, do17_t
			jp ntc_xn

p_runsort_c:		; call runsort (turbo)
			ld hl, 0
			ld (var_runsort_m), hl
			ld (var_runsort_m+2), hl
			ld hl, 0
			ld (var_runsort_prev), hl
			ld hl, 0
			ld (var_runsort_v), hl
			ld (p_runsort_rs), sp
			ld sp, p_runsort
			ret
p_runsort_r:		; end of runsort
			ld sp, (p_runsort_rs)
			ret
p_runsort_n_c:		; call runsort (normal)
			ld hl, 0
			ld (var_runsort_m), hl
			ld (var_runsort_m+2), hl
			ld hl, 0
			ld (var_runsort_prev), hl
			ld hl, 0
			ld (var_runsort_v), hl
			ld (p_runsort_rs), sp
			ld sp, p_runsort_n
			jp ntc_xn
p_runsort_n_r:		; end of runsort
			ld sp, (p_runsort_rs)
			jp ntc_xn
p_secs_c:		; call secs (normal)
			pop hl			; t
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_secs_t), de
			xor a
			ld (var_secs_secs), a
			ld (p_secs_rs), sp
			ld sp, p_secs
			jp ntc_xn
p_secs_r:		; end of secs
			ld sp, (p_secs_rs)
			jp ntc_xn

